2 \\u043f\\u043e\\u0447\\u0435\\u043c\\u0443: <\\/p><p><\\/p><ul><li>\\u0418\\u0441\\u0442\\u043e\\u0440\\u0438\\u044f \\u043f\\u0435\\u0440\\u0435\\u043f\\u0438\\u0441\\u043a\\u0438 \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u0430\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438: \\u0432\\u044b \\u0432\\u0441\\u0435\\u0433\\u0434\\u0430 \\u0441\\u043c\\u043e\\u0436\\u0435\\u0442\\u0435 \\u0432\\u0435\\u0440\\u043d\\u0443\\u0442\\u044c\\u0441\\u044f \\u043a \\u043f\\u0440\\u0435\\u0434\\u044b\\u0434\\u0443\\u0449\\u0438\\u043c \\u0441\\u043e\\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u044f\\u043c, \\u0443\\u0442\\u043e\\u0447\\u043d\\u0438\\u0442\\u044c \\u0434\\u0435\\u0442\\u0430\\u043b\\u0438 \\u0438\\u043b\\u0438 \\u043d\\u0430\\u0439\\u0442\\u0438 \\u0440\\u0430\\u0441\\u0447\\u0451\\u0442. <\\/li><li>\\u0418\\u0434\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u0438\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0442\\u043f\\u0440\\u0430\\u0432\\u043a\\u0438 \\u0437\\u0430\\u043c\\u0435\\u0440\\u043e\\u0432, \\u0447\\u0435\\u0440\\u0442\\u0435\\u0436\\u0435\\u0439, \\u0444\\u043e\\u0442\\u043e \\u043f\\u0440\\u043e\\u0451\\u043c\\u0430 \\u0438 \\u043f\\u043e\\u0434\\u0440\\u043e\\u0431\\u043d\\u044b\\u0445 \\u043e\\u043f\\u0438\\u0441\\u0430\\u043d\\u0438\\u0439. <\\/li><li>\\u0423\\u0434\\u043e\\u0431\\u043d\\u043e \\u043f\\u0440\\u0438\\u043a\\u0440\\u0435\\u043f\\u043b\\u044f\\u0442\\u044c \\u0444\\u0430\\u0439\\u043b\\u044b: \\u044d\\u0441\\u043a\\u0438\\u0437\\u044b, \\u0441\\u0445\\u0435\\u043c\\u044b, \\u043e\\u0431\\u0440\\u0430\\u0437\\u0446\\u044b \\u0446\\u0432\\u0435\\u0442\\u043e\\u0432 (\\u0432 \\u0442.\\u200a\\u0447. \\u043f\\u043e RAL\\/NCS). <\\/li><li>\\u041f\\u043e\\u0434\\u0445\\u043e\\u0434\\u0438\\u0442 \\u0434\\u043b\\u044f \\u043e\\u0431\\u0441\\u0443\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u0439 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430 \\u0438 \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u0435\\u043d\\u0438\\u044f \\u043e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u044b\\u0445 \\u0437\\u0430\\u043f\\u0440\\u043e\\u0441\\u043e\\u0432. <\\/li><\\/ul><p><\\/p><p><strong>\\u041f\\u043e\\u0447\\u0435\\u043c\\u0443 \\u0441\\u0442\\u043e\\u0438\\u0442 \\u043d\\u0430\\u0447\\u0430\\u0442\\u044c \\u0441 \\u043f\\u043e\\u0447\\u0442\\u044b? <\\/strong><\\/p><p><\\/p><p>\\u041f\\u0440\\u0438 \\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u0438 \\u043f\\u043e email \\u0432\\u0441\\u044f \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u044f \\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0430: \\u0432\\u044b \\u043f\\u043e\\u043b\\u0443\\u0447\\u0430\\u0435\\u0442\\u0435 \\u0447\\u0451\\u0442\\u043a\\u0438\\u0435 \\u043e\\u0442\\u0432\\u0435\\u0442\\u044b, \\u043a\\u043e\\u043c\\u043c\\u0435\\u0440\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u043f\\u0440\\u0435\\u0434\\u043b\\u043e\\u0436\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0435 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0432 \\u043e\\u0434\\u043d\\u043e\\u043c \\u043c\\u0435\\u0441\\u0442\\u0435. \\u042d\\u0442\\u043e \\u0438\\u0437\\u0431\\u0430\\u0432\\u043b\\u044f\\u0435\\u0442 \\u043e\\u0442 \\u043d\\u0435\\u043e\\u0431\\u0445\\u043e\\u0434\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 \\u0438\\u0441\\u043a\\u0430\\u0442\\u044c \\u0441\\u043e\\u043e\\u0431\\u0449\\u0435\\u043d\\u0438\\u044f \\u0432 \\u0447\\u0430\\u0442\\u0435 \\u0438 \\u043f\\u043e\\u043c\\u043e\\u0433\\u0430\\u0435\\u0442 \\u0434\\u0435\\u0440\\u0436\\u0430\\u0442\\u044c \\u0432\\u0435\\u0441\\u044c \\u043f\\u0440\\u043e\\u0435\\u043a\\u0442 \\u043f\\u043e\\u0434 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0435\\u043c. <\\/p